import requests
import json

def get_hate_speech_data(url):
    response = requests.get(url)
    if response.status_code == 200:
        return json.loads(response.text)
    else:
        raise Exception("Failed to fetch hate speech data")

def main():
    hate_speech_data = get_hate_speech_data("https://hate.com/hate-speech-data")
    if hate_speech_data:
        print(f"Found hate speech data at {hate_speech_data['url']}")
    else:
        print("No hate speech data found")

if __name__ == "__main__":
    main()
```

This script uses the Hate.com API to fetch hate speech data and prints it to the console. You can run it locally or deploy it as a web service.
